const CACHE = 'artzfolio-hrms-v609-2026-08-18'; /* v581: SalaryLadder promoted after a proper schema reconciliation (legacy unkeyed table renamed to backup, fresh table created with real level|shiftHours key, OWNER_GATED, backfills from the live Sheet on first sync tick -- no client fast-read this round). See decision_log/2026.08.14_HRMS_v581_salaryladder-migration_v1.md. v580_prior_note: HTML-ONLY, marker bump. Fixed stale "34 tables" Full-backup-mirror Settings card text (Batches 2-4) -- found live against production v575 (which itself still shows the even-older "36 tables", since v577's fix never deployed) while doing a live P0 check. True count is now 29 (after this session's v579 Batch 6 promotions removed Leave_Balance/Emp_Change_History/Emp_Bonus_Eligibility from the array, on top of the pre-existing Bonus_Ledger/CompensationConfig staleness fix). Also corrected the promoted-table enumeration, which had not been updated since v567 and was missing 9 tables promoted since (POSH_ICC/OneOnOneNotes/OnboardingChecklist/TnC_Acknowledgements/PettyCash/OT_Claims/Leave_Balance/Emp_Change_History/Emp_Bonus_Eligibility, plus Bonus_Ledger/CompensationConfig). No GAS logic change. See decision_log/2026.08.14_HRMS_v580_backupcount-textfix_v1.md. v579_prior_note: Leave_Balance + Emp_Change_History + Emp_Bonus_Eligibility fast-reads (Batch 6 final sweep) -- see decision_log/2026.08.14_HRMS_v579_leavebal-changehist-bonuselig-structured_v1.md. v578_prior_note: LoyaltyWallet Monthly Ledger + LoyaltyBonusLedger History owner-only fast-read wrappers added (speed pass). LoyaltyWallet's withdrawal-eligibility calc (getLoyaltyWalletStatus) deliberately NOT fast-read -- genuine 3-model money-critical computed logic, same reasoning as PettyCash. See decision_log/2026.08.14_HRMS_v578_loyalty-ledger-fastreads_v1.md. */ /* v577: PettyCash + OT_Claims promoted to real structured Supabase tables + OT_Claims owner-only fast-read wrapper added to renderOTClaims (see the GAS-side HRMS_VERSION comment for full detail; decision_log/2026.08.14_HRMS_v577_pettycash-otclaims-structured-mirror_v1.md). */ /* v554: fixed this swCode fallback blob -- it fed the owner-visible version/cache-key footer with a stale v548 stamp (this string), and contained THREE back-to-back un-terminated 'const CACHE' re-declarations below which would have thrown a SyntaxError if this fallback path ever actually executed (real sw.js failing to load). Collapsed to this single valid statement; all prior version history below is now pure comment text, not re-declared code. */ /* v548: Roster promoted to a real structured table (synthesized composite key weekStart|empId, since Roster has no natural single-column PK) with a client fast-read replicating handleGetRoster's leave-overlay/self-heal/synthesize logic, verified via a 9-case parity test against a GAS-faithful reference plus a 12,000-case IST date-arithmetic check -- inert until the hrms-read Edge Function's ALLOWED list separately activates it (held pending a live post-deploy sync verification). Also added a Tickets owner+manager fast-read (0 live rows, no money). Roster panel now shows a loading indicator instead of a silent multi-second wait. */ /* v536: GAS-only, zero HTML logic change -- ESS login now mints a Supabase JWT too (Phase 2.1b step 1 of 5), same mechanism already proven for admin logins. No client code reads or sends this JWT yet -- deliberately inert this release, see GAS changelog. */ /* v535: Leave_Conflicts promoted to a real structured Supabase table + RLS (5th table, after Leaves/Attendance/CompOff/Warnings); 3 live rows migrated with 0 mismatches; backup-array count 44->43; status card + tooltip text updated to match */ /* v534: fixed a real, live, pre-existing text bug -- the 'Sync ALL backup tables now' button title said 'Copies all 40 backup tables...' (stale since v526-v529 grew the array past 40; missed by v530's earlier '40 tables' fix, which only touched the Full-backup-mirror card description + the Verify-ALL button title, not this Sync-ALL button). Corrected to 44 (current _V281_BACKUP_TABLES length as of v533). No function, button behavior, or logic changed -- pure text fix, found and flagged during the v533 audit, fixed here as its own tiny surgical release. */ /* v533: Warnings promoted to a real structured Supabase table + RLS (4th table, after Leaves/Attendance/CompOff); 8 live rows migrated with 0 mismatches; backup-array count 45->44; status card + tooltip text updated to match */ /* v531: golden-master PASS status card + removed one-time RLS test button (was v525, never clicked, checks proven via direct DB verification) — see changelog */; // v530_stale-40tables-count-fix 2026-08-08. LIVE-AUDIT-FOUND BUG, HTML-only, two static description strings under the "Full backup mirror" card said "40 tables" -- true count is 46 as of v529 (Tickets/Candidates/OfferLetters/Assets/PulseQuestions/PulseResponses added v526-v529), a genuine stale-count defect this text has no way to self-correct since the client has no live read of the server-side _V281_BACKUP_TABLES array. Both occurrences corrected to 46. No function, button, or logic changed -- pure text. // v529_pulsesurvey-backup-mirror 2026-08-08. GAS + Supabase schema only, zero HTML logic change -- 'PulseQuestions'+'PulseResponses' added to the nightly backup mirror, no new UI. Closes the last of the 4 zero-backup-coverage modules. // v528_assets-backup-mirror 2026-08-08. GAS + Supabase schema only, zero HTML logic change -- 'Assets' added to the nightly backup mirror, no new UI. // v527_recruitment-backup-mirror 2026-08-08. GAS + Supabase schema only, zero HTML logic change -- 'Candidates'+'OfferLetters' added to the nightly backup mirror, no new UI. // v526_tickets-backup-mirror 2026-08-08. GAS + Supabase schema only, zero HTML logic change (marker-only) -- 'Tickets' (Helpdesk) added to the nightly backup mirror, reuses the existing Sync/Verify buttons, no new UI. // v525_rls-pilot-selftest 2026-08-08. Adds one owner-only Settings button, "Run Full RLS Test (Leaves pilot)", calling new GAS action rlsPilotSelfTest -- automates the 4 remaining checks (self-scope / cross-employee denial / expired JWT / bad signature) on the v_pilot_leaves_self_select RLS policy applied live 2026-08-08. No other logic touched. // v524_config-header-fix-retroactive-plus-jwt-test-mint 2026-08-07. TWO items, both GAS-side, this HTML file's edits are the two version markers only. (1) RETROACTIVE DOCUMENTATION of a live incident fixed by a DATA edit, not a code edit: Config sheet cell A1 (the header row every getCfg()/sheetToObjects() lookup depends on) was corrupted from the literal text "key" to "kA1ey" -- root cause unknown (not caused by any release in this changelog), effect was server-side apiToken lookups returning empty, which is what produced "This device is not authorized" on every device including ones that had never needed to re-enter a token before. Fixed by editing the one corrupted cell back to "key" (owner-approved before the edit), verified live via the app's own pingToken diagnostic (before: serverLen 0; after cache TTL expired: serverLen 41, match true) and by a full reload rendering correct Config-dependent data. No HTML, GAS or SW code was broken or changed to cause or fix this -- the code was always reading the cell correctly, the cell's own content was wrong. (2) NEW: an owner-only diagnostic button, "Test Supabase JWT Mint", that calls the new GAS action mintTestSupabaseJwt to mint a short-lived test JWT via the existing v520 infrastructure (_v520MintSupabaseJwt_, live-armed now that SUPABASE_JWT_SECRET is configured) and verify it against the real Supabase database by attempting a read on the PunchDefers table (which carries the v518 deny-all-to-anon/authenticated RLS policy) using ONLY the JWT for auth, never the service_role key. A 401/403 means the signature is invalid (wrong secret or malformed token); an HTTP 200 (regardless of row count, since RLS denies all rows to this role) means the signature validated correctly. The JWT itself never leaves the server -- the button reports only a pass/fail verdict, never the raw token. This proves the v520 minting infrastructure actually produces a Supabase-valid JWT before any RLS policy is ever written to depend on it, closing the loop opened in v520 ("cannot be live-tested... until the owner adds that secret") now that the secret exists. // v521_backupsync-timebox-resume 2026-08-07. GAS-only, zero HTML logic change (version markers only). Fixed backupSyncTick (the 40-table nightly Supabase backup mirror) hitting GAS's ~6-minute execution ceiling and getting killed mid-run 2 nights running (8/5, 8/6 -- seen live via GAS failure-notification emails). Was an unbounded loop with no time budget and no resume point; now time-boxed to 5 minutes with a resumable cursor in Script Properties, same pattern already proven on the sibling function sbAutoSyncTick (v490). The "last successful backup" timestamp Settings reads only advances once a full 40-table pass actually completes across however many runs it takes -- a partial night can never look finished. // v520_supabase-jwt-mint-infra 2026-08-06. Phase 2.1b infrastructure ONLY, GAS-side, zero HTML logic change (this file's edits are the two version markers only). Added _v520MintSupabaseJwt_ -- a real RFC 7519 HS256 JWT minted at admin/owner/manager/supervisor login (handleAdminLogin, both success branches), shaped for Supabase's GoTrue/PostgREST so a FUTURE RLS policy can read custom claims (empId, adminRole) instead of every read going through hrms-read's service_role key. KILL-SWITCHED: reads Config key SUPABASE_JWT_SECRET; empty/missing (confirmed empty 2026-08-06 via two independent checks) means the function returns null and the login response is byte-identical to v519 -- no client change needed or made. No RLS policy anywhere depends on this yet. Cannot be live-tested against real Supabase until the owner adds that secret (Project Settings -> API -> JWT Keys -- a different, more sensitive credential than the anon/service_role keys already in Config; no available MCP tool exposes it). ESS and kiosk logins are deliberately untouched this release -- kiosk has no signed-in identity, ESS is a separate, larger blast radius for its own release. // v519_boot-settings-retry-fix 2026-08-06. Root-caused live: v516's Employees Supabase fast-path silently broke the _v260Boot retry's ability to detect a Settings/GAS-specific cold-start failure, because "any of the 3 boot calls succeeded" stopped meaning "GAS is healthy" once Employees could succeed independently via Supabase. Fixed by also retrying when Settings specifically didn't come back ok, not only when all three failed. Activities deliberately excluded (confirmed genuinely 0 rows, no benefit to retrying it). HTML-only, one added condition, no other logic touched. // v518_settings-fastpath-plus-rls-hardening 2026-08-06. Added a Supabase fast-path read for getSettings, wired ONLY into the two cold-boot call sites (_v260Boot, loadAppData) -- ~14 other call sites deliberately left on the untouched GAS path (several are post-save verification reads where a Supabase mirror lag would be actively dangerous). Guards against ConfigPublic being empty before the first save since deploy (treated as not-ready, falls back to GAS, never fabricates an empty settings object). Separately, database-side only, no HTML/GAS logic change: Phase 2.1 RLS hardening -- 53 explicit deny-all policies for anon/authenticated added to every table that had RLS enabled with zero policies (verified live before and after that this changes nothing for the app, since all real reads go through Edge Functions on service_role and bypass RLS entirely), and the rls_auto_enable() SECURITY DEFINER advisory closed properly (REVOKE EXECUTE FROM PUBLIC; verified the trigger itself still auto-enables RLS on new tables). Security advisor: 2 WARN + 53 INFO -> zero findings. v515_pendingatt-reimb-mirror-plus-backupsync-repair 2026-08-06. HTML unchanged (this release is GAS-side: mirror list + trigger repair) -- version bumped for 4-way lockstep only. GAS side: added 'PendingAttendance' and 'Reimbursements' to the _v490Json mirror rotation (owner request) using the SAME _sbMirrorJson_ path already proven for 9 other tables -- data now flows into Supabase, no client fast-read wired yet (that's a separate, later step, same discipline as every prior migration stage: mirror -> verify parity -> THEN read from it). SEPARATELY, found LIVE during this session that the 40-table backup-sync trigger (_V281_BACKUP_TABLES, daily 2am) had gone stale -- last real sync 2026-08-03, three days behind despite the trigger existing in code since v281. Re-installed the trigger live via the already-built, owner-gated installBackupSync handler, then ran an immediate full catch-up sync. No code bug caused the staleness -- the trigger had simply been removed/reset at some point (this app deletes-then-recreates triggers by name during several repair operations, e.g. v477's fix, which can drop an unrelated trigger if run at the wrong moment). v514_employees-fastpath-deadtable-fix 2026-08-06 changelog preserved below for provenance: REAL FUNCTIONAL FIX, found in the same live-audit session as v513: renderEmployees()'s Supabase fast-path, and the Settings "Speed Test" diagnostic, both hardcoded the table name 'employees_public' -- a view REMOVED long ago (before v511/512) after it was found to leak salary/mobile/dob. Since that removal, EVERY attempt to use this fast path has silently 403'd and fallen back to slow GAS -- meaning "Fast Mode ON" for Employees has done nothing, ever, since that security fix shipped, and the Speed Test button has always incorrectly reported the fast path as "failed." Live-reproduced: clicking Speed Test returned "Direct Supabase: 1902ms (failed)". Root cause found by grepping the whole file for the dead table name after finding one broken caller and asking whether there were others -- there were, exactly one more. Fixed both call sites to use 'employees_roster_v', the real, live-proven-safe replacement (0 banned columns). Checked all 42 downstream consumers of the resulting array for any salary-field access before making this change -- zero found, safe. v513_syncgrid-tooltips-liveaudit 2026-08-06 changelog preserved below for provenance: HTML-ONLY, ZERO LOGIC CHANGE. Owner deployed v512, then asked for a live audit of everything built. Drove the LIVE v512 tab via Chrome MCP: expanded all 6 redesigned Settings cards for real, found one genuine gap the static-HTML edit pass in v512 could not have caught — the 8-table Sync/Check grid in the Migration Control Center card (id v280-tables) is built at RUNTIME by v280RenderTables(), so it had zero title tooltips even after v512, including on SalaryRecords and SalaryRegisterMeta, the two most sensitive buttons on the page. Fixed: every Sync/Check button in that grid now has a title tooltip; SalaryRecords/SalaryRegisterMeta/Transactions get an explicit "money-adjacent" badge + a note that syncing them only refreshes the backup mirror and never exposes salary to the browser (hrms-read's allow-list still excludes both — verified live same day). Everything else in v512 was live-audited and found correct: 4-way version lockstep confirmed live, all 6 cards render with their EVERYDAY/SECURITY/DANGER ZONE badges intact, toggleCard()+localStorage persistence works, golden-master button proven live (see decision log). v512_admin-console-descriptions 2026-08-05 changelog preserved below for provenance: HTML-ONLY, ZERO LOGIC CHANGE — every onclick/function untouched. Rewrote the Settings tab's 6 Supabase/Speed/Health cards (~50 controls total) from a wall of unlabeled buttons into a plain-language admin console: every button now carries a persistent visible one-line description (not just a hover tooltip, since factory-floor use is often touch-only) plus a risk badge — EVERYDAY (safe any time, never touches pay), SECURITY/VERIFICATION (read carefully, built to fail safe), or DANGER ZONE (salary-critical, gated behind golden-master PASS). Card 1 (Speed & Health, the one on screen when this was asked for) got the full treatment: 11 buttons regrouped into EVERYDAY (monitor/diagnose) and SECURITY (the 4 cloud-key controls). Cards 2-4 (Direct Read, Keep-Warm, Attendance Parity) and the two Advanced cards (Migration Control Center, Supabase Speed Sync & Health) got matching badges and filled in every previously-untooled button with a title tooltip. Not a single onclick handler, function name, id, or backend call changed — verified by diff against v511 and by re-reading every edited region end to end. // v511_supabase-boot-reads-stage1 2026-08-05. STAGE 1 OF THE SUPABASE MIGRATION (Option A, non-salary reads only). SCOPE, STATED HONESTLY: the plan named five boot reads to move -- getPendingAttendance, getPendingLeaves, getTodayAttendance, getReimbursements, keepWarmStatus. Only TWO were actually movable today, and the other three are not moved as an oversight -- they are architecturally blocked, and here is why. getTodayAttendance already had a fast path (_v303TodayFast via _v303TwoPhase, live since v488) at the Dashboard call site -- untouched here; its OTHER call site (the kiosk Who's-In panel) was DELIBERATELY reverted off Fast Mode in v492 because the fast read carries no employee names, so it is left exactly as v492 set it. getPendingLeaves reads the Leaves table, which IS mirrored to Supabase, and already had a fast path at ONE call site (the Approvals Inbox, v315 -- untouched). This release extends the SAME pattern, behaviour-identical on any miss, to the three call sites that still went to Apps Script on every single call: refreshApprovalsBadge() (fires at every admin login), renderDashboard() and renderLeaves() -- none of the three pass an approverRole filter and none need more than the leave list/count, so the plain Leaves-table read is a safe substitute, exactly as at the existing v315 site. NOT MOVED, verified live against the Supabase database before writing a line of code: getPendingAttendance reads the PendingAttendance sheet and getReimbursements reads the Reimbursements sheet (which carries claim amounts -- money-adjacent). NEITHER sheet is in the Supabase mirror -- _sbResolveTable_ lists only Employees/Leaves/Attendance/Transactions/Points/Holidays/SalaryRecords/SalaryRegisterMeta, and a direct query of the live database confirms no PendingAttendance or Reimbursements table exists there at all. Building a fast path for either would first require adding the sheet to the GAS mirror rotation, backfilling it, verifying the count matches, and widening the hrms-read Edge Function's table allow-list -- a materially bigger and separate change, deliberately left for its own release rather than rushed into this one. keepWarmStatus was also not moved: it answers 'is a specific Apps Script trigger installed', which is Apps Script's own live state with no Supabase equivalent to read, and it never runs on the boot path at all -- only from a Settings status card. THE NEW HELPER: _v511PendingLeavesFast() reuses the existing _sbDirectRead/_v265Flag/_v424NonSalaryFastAllowed gate unchanged (Fast Mode owner-only by default, broadened to manager/supervisor for the Leaves table specifically, exactly as v424 already allows), reads the Leaves table once, and refuses to trust the answer if it comes back at or above the 1,000-row PostgREST page cap (283 rows live today -- the guard cannot fire yet, but is in place before the table grows into it). Any doubt at all returns null and the caller falls straight through to the untouched API.call. ONE flag reverts every change here: az3_directRead=off (the existing Fast-Mode toggle) makes all three new call sites behave byte-for-byte as they did in v510. NOTHING about salary, attendance, leave, timesheets, payslip or payroll logic is touched anywhere in this release; calcMonthlySalary is untouched. Timed live before/after on the panel -- see decision log 2026.08.05_HRMS_v511-supabase-boot-reads-stage1. // v502_exit-type-and-attendance-safety-card 2026-08-05. FIX-1, AND IT WAS A SILENT DATA FAULT THE OWNER FOUND BY ASKING A QUESTION: 'how do I mark somebody terminated, or absconding?' The answer was that you could not. The Direct Exit button sent exitType 'Mutual' HARD-CODED, so every immediate exit - a dismissal for cause, an absconding, a contract simply ending - was filed as a mutual separation on the Exits and Notices record, in the F&F, and in every export made from them. The free-text reason might have been right; the CLASSIFICATION was always wrong, for everybody, and nothing on screen revealed it. Direct Exit now ASKS - Resigned, Terminated, Absconding, Mutual, Contract Ended, Retired - defaults to nothing so it cannot be answered by accident, refuses to run until it is answered, states the choice in the confirmation, and the backend stamps it on the EMPLOYEE record as well as the notice row, so a report can finally tell a termination from a resignation. The Employees sheet already had an exitType column; this path had simply never written to it. The two other exit routes are unchanged and were already correct: 'Initiate Notice / Exit' for a resignation or termination served with notice, and Approvals - Exit Alerts - 'Archive to FnF draft' for an absconding the system has detected from consecutive unapproved-leave days, which already records Absconding. FIX-2, FINISHING v501'S SAFETY NET. The auto-UL circuit breaker - the check that stopped the system marking 26 of 29 staff absent on a day the app was down - lived entirely in the Config sheet: two thresholds nobody could see and a blocked-day alert that could only be cleared by hand-editing a cell. By this project's own rule that is not a finished feature. There is now a card, 'Attendance Safety - stop a bad day marking everyone absent', under Settings - Shifts & Time, showing whether a day is currently blocked and why, with the two thresholds editable and a button to clear the alert once the day has been set by hand. NOTHING about salary, attendance, leave or payslip logic is changed: calcMonthlySalary is md5-identical for the fourteenth consecutive release - BUT SAID PRECISELY, because an audit caught the sentence being broader than the truth: choosing ABSCONDING does change the F&F settlement. That is existing, deliberate policy in handleCalcFnF - absconding forfeits leave encashment and adds the uninformed-absence penalty of roughly three days pay - and it simply never fired on this route before, because the route always said 'Mutual'. The confirmation now spells that out before it is agreed to, and the F&F PREVIEW button sends the same classification as the save, so the figure you check is the figure you get. AUDIT FIXES INSIDE THIS RELEASE, two of them blockers, both the same shape - a card that reports success while doing nothing: getSettings returns an ARRAY of key/value rows and the card read it as an object, so it always showed the built-in defaults and printed a green 'no day has been blocked' even on a day one HAD been blocked; and the three new config keys were never added to the backend's allowed-keys list, so handleUpdateSettings silently rejected every write and still answered ok:true - Save and Clear were decorative. Both fixed, and both buttons now check what actually happened, distinguish a timeout from a failure, and refuse to show anything at all if the reply is not the shape it should be. Also fixed: one vocabulary for exit types, matching the values Initiate Notice already stores, so a report cannot end up treating Resigned and Resignation as two things. // v501_slip-bundle-and-auto-ul-breaker 2026-08-04. FIX-1, WHY 'ALL SLIPS' TOOK EIGHT MINUTES - and it was never the PDF. jsPDF, html2canvas and JSZip all run in this browser and are fast. Building each slip fired THREE separate Apps Script calls, once per employee: the day-by-day projection, the leave balances and the reimbursements. For 29 staff that is about 87 round trips at 7-24 seconds each against a backend that allows four at a time - precisely the eight to fifteen minutes measured live on 4 August, behind a 'Please wait' that said nothing. All three are now fetched for EVERYONE in one chunked call (new backend action getSlipBundleBulk), and each slip is seeded with the answer so the three existing per-employee enrichers short-circuit on their own idempotency guards. No slip layout changes, no figure moves, and if the prefetch fails for any reason the old per-employee path runs exactly as before - slower, never wrong. Applied to all three slip buttons: the combined PDF, the separate PDFs and the ZIP. FIX-2, A REAL PROGRESS BAR. The slip pack now shows 'Preparing salary slips 12 of 29' with a bar and a plain explanation, including while it waits out a busy backend, and the bar is removed on every path including failure. A silent multi-minute wait is indistinguishable from a hang - that is the same lesson this project learned on the payroll screen, applied here. NOTHING about salary, attendance, leave or payslip layout is changed in this file: the only edits are the prefetch helper, the row-seeding helper, the progress helper, three slip call sites and one entry in the silent-actions list. // v500_retry-rounds-and-keep-cancellations 2026-08-04. EVERYTHING IN THIS RELEASE CAME OUT OF RUNNING v499 AGAINST THE LIVE SYSTEM RATHER THAN READING IT. FIX-1, AND IT IS THE ONE THAT MATTERS: v499 decided that a VOIDED or REJECTED prize row does not count as awarded, so a recompute would create it again. An audit argued for that and the reasoning was plausible. The live sheet says it is wrong. Every row in the production Bonus_Ledger is a Perfect Attendance Bonus for 06/2026 carrying 'VOIDED FULL 2026-07-10 by owner: Poor performance' - the owner deliberately withheld Rs 4,000 from four people, and Perfect Attendance has never excluded voided rows from its own duplicate check, so those four have correctly stayed unpaid. v499 would have made the points prize behave the opposite way: cancel a prize, recompute, and the money comes back. A recompute must NEVER resurrect a payment the owner has cancelled. Voiding is a decision, not a draft. A voided or rejected row now counts as awarded, exactly as Perfect Attendance has always treated it; to genuinely re-award a month, DELETE its prize rows in the Bonus_Ledger sheet - there is no delete-bonus button in the app, only void - or add the corrected prize by hand through Bonus and Loyalty. Both are deliberate acts, which is the point. The concern that motivated v499 - a half-written round frozen forever - is already solved by writing the whole round in ONE atomic call. FIX-2, THE ROUNDS NOW FINISH. Timed against the live backend: v499's 75-second rounds returned nine employees when Google was quiet, four when it was not, and the third round was abandoned by the browser at 150 seconds. No employee is slow - the SAME person failed and then succeeded two minutes apart. Apps Script was queueing, because this account also runs twelve background triggers. At rest between bursts a plain call answers in 5.9 to 8.7 seconds. So: rounds drop to 55 seconds (measured: five employees, 66 seconds of wall clock); there is an eight-second breather between rounds so Google can drain instead of refusing; each round is RETRIED up to three times with a growing pause before the register is declared incomplete; and a payroll round is allowed its own 300-second ceiling instead of the 150 seconds an ordinary button gets. The retry is what actually made the run complete - a round failed twice with a 404 and succeeded on the third attempt, where v499 would have thrown the whole register away. Retrying is safe precisely because of Option B: re-running the same cursor recomputes the same people and a prize already awarded for the month is never written twice. HONEST ESTIMATE, CORRECTED: 15 to 25 minutes for a full month, not the 10 to 15 v499 claimed. PROVEN LIVE THIS ROUND: ten employees accumulated across rounds with ZERO duplicates and strict A-Z order; the cursor, the roster fingerprint and the accumulation all behave; Abhishek Joel computed to 16714.67, matching his July payslip to the paisa. NO salary formula, attendance rule, leave rule, payslip layout, payout value or default is changed: calcMonthlySalary is md5-identical for the release in this chain and in fact unchanged since v464. The one thing that DOES change is a pay-run SETTING, said plainly rather than hidden behind the usual sentence: the default size of a recompute round drops from 75 to 55 seconds and its ceiling from 80 to 70. AUDIT FIXES INSIDE THIS RELEASE, because the first draft of it was withheld too: the retry loop originally retried ANY unsuccessful answer, which would have re-sent a finalised month's polite refusal four times behind the words Google is busy - it now retries ONLY a lost or timed-out reply, never a considered no; a wall-clock deadline of 45 minutes was added, because a round cap alone allowed a theoretical eleven-hour run behind a promise of twenty-five minutes; the abort message now quotes the ceiling that actually applied rather than the general one; and three comments that still described the v499 behaviour this release reverses were deleted. THE 15 TO 25 MINUTES IS AN UPPER BOUND, not a measurement: five employees in 66 seconds implies about eight minutes for 29 people if nothing is dropped, and the wider figure is there to cover the retries that the live run showed are normal. // v499_one-button-payroll-and-option-b 2026-08-04. THE OWNER DECIDED OPTION B: a prize is awarded ONCE, at first approval, and never again. That decision is implemented in the backend, and it is what finally makes a working Recompute All possible. THE ONE BUTTON. Google kills any Apps Script request at SIX MINUTES; a recompute costs about fifteen seconds per employee, so 29 staff need about seven and a half minutes in one request. Recompute All was never slow - IT DID NOT FIT, on every version ever shipped. This screen no longer sends one request: it asks the server to compute as much as fits, take a marker, and carry on from that marker, round after round, until the server says done - showing a progress bar and a plain explanation while it works, because a silent two-minute wait is indistinguishable from a hang. Same engine, same people, same figures; the request is divided, the calculation is not. THREE FAULTS OF THE WITHHELD v497, CLOSED BY CONSTRUCTION: (1) a partial run is never presented as complete - what arrived is labelled INCOMPLETE with the number of people missing and the reason; (2) that warning is rendered INSIDE the register's own banner slot, so the container repaint that erased it in v497 now renders it; (3) Save to Records REFUSES an incomplete register outright, because saveSalaries overwrites the whole month and a part-finished run would leave uncomputed people carrying stale figures. THREE BUTTONS BECOME TWO, and the duplicate is gone: 'Recompute All', 'Recompute Selected' and 'Recompute (live)' were three buttons running TWO commands - 'Recompute (live)' called the identical function as 'Recompute Selected'. There is now one button that does the whole month and one that does only the people you tick, both plainly labelled, and the third has become a whole-month recompute where it sits on the saved register. NOTHING about salary, attendance, leave, timesheets or payslip layout is changed in this file: the only edits are the recompute call, the incomplete banner, the save guard and the button labels. // v498_release-the-stuck-slots 2026-08-04. ONE BUG, AND IT IS WHY THE KIOSK AND THE DASHBOARD STOPPED. This app allows only FOUR backend calls at a time. A call that finishes releases its slot; but the fetch had NO TIMEOUT AT ALL, so a call Google never answers NEVER settles and NEVER releases its slot. Four unanswered calls consume every slot permanently, and from that moment EVERY other call queues behind them forever - the dashboard never finishes loading, the kiosk sits on 'processing', and nothing recovers until the page is closed. That is exactly the reported behaviour: 15-20 minutes for a dashboard and then nothing, and staff unable to clock in. It also explains why a raw call typed into a console answered in 6.9 seconds while the app itself was frozen - the console does not go through the limiter. FIX-1: the WHOLE wait is now budgeted, not just the fetch. The clock starts BEFORE a call queues for a slot, so a call that spent its budget waiting gives up at once instead of starting a fresh wait of its own. Reading the reply body now also happens inside the budget and inside the slot - a reply that stalls half-way through would otherwise hang forever one layer down - and the honest cost of that is that a slot is held a few milliseconds longer than before. The slot is released on EVERY path, including a browser too old to cancel a request at all. AN UNCLAIMED BONUS FOUND BY THE AUDIT: in v496 a call that never settled kept the in-flight counter above zero forever, which PERMANENTLY DISARMED the v493 stuck-curtain watchdog. v496 therefore had the deadlock and a defeated watchdog at the same time. Bounding the call re-arms it. FIX-2, and an audit correctly called this a blocker: a lost answer returns early and was therefore skipping the one toast this app relies on to announce a failure. Twenty-five screens read an answer without checking it first, so a lost answer was landing as a green '0 employees clocked out', a Rs 0 balance, or 'No salary records found'. Every lost answer, every timeout and every command that could not be sent now says so in plain words, once, before it returns. A failure must look like a failure. A SECOND AUDIT CORRECTION INSIDE FIX-2: the first draft reused the eight-action retry list written in v492 for the slow owner buttons, but only ONE of those eight is ever reached on this path - so 27 of the 28 calls a login fires would have had no retry and the app would not have healed without a reload. Any plain read now retries; deliberately NOT anything that merely is not a write, because calcAllSalaries would pass that test and it appends prize rows. AND THE TWO FAILURES ARE NOW TOLD APART, which matters on the factory floor: a request that TIMED OUT may have run, so a punch must not be blindly re-scanned; a request that gave up while queueing NEVER REACHED GOOGLE AT ALL, and the screen now says press it again. FIX-3: the payroll screen catches a thrown call and shows the error instead of spinning forever. FIX-4, stated precisely because a false safety claim has preceded three of the last five incidents: the cache wrapper was swallowing an error thrown by the call itself and then quietly sending the same command again, so a write could be attempted SIX times. It is now at most THREE, and a write that fails that way announces itself instead of clearing its spinner in silence. Repetition on a plain network error is REDUCED, not eliminated. ONE CEILING, ONE PLACE: the slow owner buttons waited 150 seconds while ordinary calls waited forever; both now read a single constant, set to 150s. It is deliberately NOT lower - a 5-employee payroll recompute was measured at 119.7s, so a shorter ceiling would have started killing work that legitimately runs today. WHAT THIS DOES NOT DO, said plainly: it does not make Apps Script fast. If the backend is merely SLOW rather than stuck, a 150s ceiling now turns some very long calls into visible failures that v496 would have waited out - that is the intended trade, because a screen that says so and retries beats a screen that hangs. And Recompute All for all 29 staff still cannot finish inside Google's 6-minute execution limit; that needs the resumable server-side run, which is the next release. NOT IN HERE: the batched Recompute All built as v497 was AUDITED AND WITHHELD - five faults in its own new code, including that batching changes the money because the bonus ledger is snapshotted per request. It is parked in _WITHHELD_v497_do_not_deploy and must not be deployed. No salary formula, attendance rule, leave rule, payslip layout, payout value or default is changed anywhere in this release: calcMonthlySalary is md5-identical and the backend has ZERO logic changes. // v496_month-closes-only-when-everyone-is-paid 2026-08-04. TWO FAULTS, both root-caused from the owner's own screenshot showing a green LIVE FIGURES banner above 'Rs 0 Total Net Payroll, 0 Employees'. FAULT-1, THE EMPTY REGISTER. Apps Script now takes 54-60 seconds on a whole-sheet read and past that point Google ABANDONS the request and answers with its own status page - a body that looks like {status:ok, app:ArtzFolio HRMS v495, version, ts}. That is VALID JSON, so the parse guard added in v492 let it straight through, and the payroll screen's guard tested res.ok === false, which is FALSE for a reply that has no ok field at all. The screen then fell through to res.salaries || [] and rendered an EMPTY register under a green LIVE banner. A failed fetch was presented as a successful payroll run of zero employees - the exact rule this system is built on breaking. FIX: API._rawCall now RECOGNISES the status-page shape and turns it into a real failure (and releases the loading curtain, which the v493 lesson requires), and the payroll screen now demands res.ok === true before it will render a single figure. Anything else is an error message, never an empty register. FAULT-2, THE MONTH THAT CLOSED ITSELF. The owner is right and the old rule was wrong. Since v172 the freeze read: if ANY ONE approved salary row exists for a past month, the WHOLE month is FINALIZED. One employee left, his F&F was generated and saved, and that single row closed July for all 29 people. Worse, an F&F-settled employee is DELIBERATELY EXCLUDED from the monthly register by the v61 double-count guard - so the month was being closed by a row belonging to somebody who is not part of that register at all. NEW RULE, which is the owner's own words: a month is finalised ONLY when every employee who belongs in that register already has an approved salary record. The expected population is the full Active / Notice / Notice Period list MINUS anyone settled through F&F for that month, and it is measured before any employee-picker narrowing so recomputing three people cannot make a month look closed. If even one person is still unpaid the month stays OPEN and recompute proceeds normally, as many times as needed. The freeze itself is kept for the genuine case - a fully paid month is still protected and still overridable. NO salary formula, no attendance rule, no payout value and no default is changed: calcMonthlySalary remains md5-identical. v495_close-the-salary-leak-for-real 2026-08-03. Carries v493 (frozen-screen fix + watchdog) and v494 (boot-weight removal). THE HEADLINE IS A LIVE P0 THAT I HAD PREVIOUSLY REPORTED AS CLOSED AND HAD NOT. On 2 August the salary leak was 'fixed' by removing the view employees_public from the hrms-read allow-list. That allow-list is a rule inside one Edge Function. It is NOT what PostgREST consults. The view itself still existed, was SECURITY DEFINER, and the anon role still held SELECT on it - and the anon key is printed in the app's own public HTML. So for the last day and a half, anybody on the internet could read every salary and every mobile number with a key that ships in the page. REPRODUCED, not theorised: a plain GET to rest/v1/employees_public with that key returned id, name, salary 14000, mobile 9573943885. CLOSED, and proven closed: employees_public is DROPPED; employees_roster_v and attendance_month_v are now security_invoker=on with SELECT revoked from anon and authenticated; anon now gets permission denied on both and 'table not found' on the dropped one, while the app's own path through hrms-read (service key) still returns 53, 1666, 244 and 1699 rows. THE LESSON, recorded so it cannot happen a third time: an allow-list inside one function is not an access control - it only governs the door it sits on. Postgres grants and RLS govern the database. A leak is not closed until the ORIGINAL attack is re-run and fails. Also this round: the sanitised roster view employees_roster_v was created and PROVEN clean (explicit column list, zero of 34 banned money and PII columns, checked in the schema AND in the live payload) and is allow-listed in hrms-read v8 - but the client code to consume it was REMOVED before shipping, because an independent audit proved it was dead code with no caller on any screen, and because designation is filled in for only 9 of 53 employees and department for 10, so it would have delivered nothing visible today. The view is in place and locked down for when those fields are filled in. This HTML is therefore byte-identical to v494 apart from the two version markers. NOTHING about salary, attendance, leave, timesheets, payslips or payroll logic is touched anywhere in this release. // v494_take-the-weight-off-the-boot 2026-08-03. THIS RELEASE CARRIES v493's OUTAGE FIX AND THEN TAKES WORK AWAY, because the honest finding is that the speed project has been ADDING load, not removing it. MEASURED LIVE TODAY against the real backend: an action with NO HANDLER AT ALL - the dispatcher simply reports unknown action - took 14.6 SECONDS. getSettings took 14.6s. keepWarmStatus took 14.9s cold and 5.6s warm. That is the floor: every single Apps Script call costs about 6 to 15 seconds no matter what it does, so the ONLY thing that makes a screen faster is MAKING FEWER CALLS. And I had been adding them. v473 added a background getReadToken refresh on every boot; v489 added a background getPunchToken refresh on every boot; v489/v491 then made each of those calls ALSO do a Supabase network round trip AND take an Apps Script script lock, on the boot path, competing with clock-ins. AUDIT CORRECTION, because overstating a fix is how the last three went wrong: the honest saving is ONE Apps Script call on most devices and TWO on the owner's, not two everywhere, and ZERO on a first-ever boot where both keys still have to be fetched. Those calls were background work, not on anybody's visible clock. The real win is narrower and still worth having: it frees one or two of the four concurrency slots during the boot storm, and it removes one or two acquisitions of the app-wide script lock that clock-in queues behind. v494 removes exactly that and nothing else: both refreshes are now time-boxed to once every 12 hours, and the repair path is not weakened but sharpened - a key that is actually REFUSED (401 from the cloud) sets a repair flag that forces an immediate re-fetch on the next call and asks the backend to re-push it. A working key is never re-fetched; a broken one is repaired at once. Also carried from v493: the reference-counted Please-wait curtain that froze the app is fixed at its source and given a watchdog floor. NOTHING about salary, attendance, leave, timesheets, payslips or payroll is touched anywhere in this release - the only files changed are the two token refresh paths, one 401 branch, and the version markers. // v493_release-the-stuck-please-wait 2026-08-03. ONE MISSING LINE TOOK THE APP DOWN, AND IT WAS MINE. After v492 the app sat on Please wait forever, across refreshes, for two hours. PROVEN LIVE, not guessed: the backend was healthy the whole time (getSettings answered with valid JSON in 14.6 seconds, serverVersion v492), the page had rendered completely behind the curtain, and there was not one console error. The overlay is REFERENCE COUNTED - show() increments a counter, hide() decrements it, and it only lifts at zero - and the JSON-parse guard I added to API._rawCall in v492 RETURNED from inside its catch without calling hide(). One unparseable reply therefore left the counter stuck above zero and the curtain down permanently, with the working app and the working backend sitting behind it. Forcing the overlay off in the owner's live browser revealed a fully functional app, which is what identified it. FIX-1: that path now hides the overlay before it returns. FIX-2, and this is the one that matters more: a counter that can only be corrected by perfectly balanced code will fail again the next time anybody writes an early return, so it now has a floor under it. A watchdog checks every ten seconds and, if the curtain has been up for more than 90 seconds with no real activity for the last 20, releases it, records the reason, reports it to crash reporting and tells the owner in plain words. A stuck screen is now a 90-second inconvenience instead of an outage. No salary formula, no attendance rule, no payout value and no default is changed anywhere in this release. // v492_undo-the-cachebuster-and-simplify-payroll 2026-08-03. FIX-1 AND IT IS MY OWN REGRESSION: every slow owner button broke after v490 - Check the Cloud Keys returned a SyntaxError about an unexpected < , and Rotate the Kiosk Punch Key, Check and Repair Triggers and the payroll comparison all timed out at 150 seconds. ROOT CAUSE PROVEN by an A/B test from the owner's own browser against the live backend, same action and same body, four calls: WITHOUT the cb parameter 200 and valid JSON in 14.9s then 5.6s; WITH it 200 in 20.0s once and then HTTP 404 with an HTML page in 38.0s. Apps Script does not tolerate an unknown query string on a POST to exec - it answers with a 404 web page, the browser cannot parse that as JSON, and that is exactly the error on screen. The cache-buster I added in v490 to stop a rare lost reply instead caused a total failure of every slow button, and it is removed. Kept from v490: the explicit content type, never auto-retrying a command that is unsafe to repeat, and recognising a page-instead-of-an-answer, now reported in plain English with the HTTP code instead of a raw parser error. FIX-2 THE KIOSK PANEL SHOWED EMPLOYEE CODES INSTEAD OF PEOPLE, also mine: v491 read that panel through the kiosk punch key, which deliberately carries NO names, and joined names from a local cache that is empty on a phone. A screen that lists people must show people, so the panel is back on the Apps Script read that carries the full identity, getTodayAttendance now also returns designation, and every row shows the complete identity - name, designation and department, shift window, and since-time - the same golden name structure used everywhere else. The punch-key fast read is kept where it needs no names: the kiosk clock-in/clock-out direction check. FIX-3 PAYROLL IS SIMPLE AGAIN. Recomputing a finalised month had become a research project with two jargon buttons in the wrong order. The plain truth was buried: RECOMPUTE ONLY WORKS OUT AND SHOWS THE FIGURES, it does not write the saved register, and nothing is saved until Save to Records is pressed. So the panel now leads with one button that just does it after one plain confirmation, and the two comparisons are demoted to clearly numbered optional steps in the order they should be used, each labelled with how long it takes. The comparison also honours the employee picker so it can answer in seconds for a few people instead of timing out on the whole company. No salary formula, no attendance rule, no payout value and no default is changed anywhere in this release. // v491_settings-snapshot-and-kiosk-fastread 2026-08-03. CORRECTION FIRST: v490 said a status-page reply meant 'the command never ran and nothing was changed'. Live evidence disproves it - the cloud read key has been rotated TWICE and the originally leaked key is DEAD (proven: hrms-read now refuses it). The rotations ran; only their answers were lost. The true statement is that a status-page reply means THE REPLY IS LOST AND YOU CANNOT TELL WHETHER THE COMMAND RAN, which is exactly why a command that is unsafe to repeat is never retried automatically. v491 fixes that wording everywhere and adds the missing piece: a Check the Cloud Keys button that reads the live state - which keys exist by their last six characters only, whether a retiring key is still inside its grace window, and the last rotations from the Audit log. FEATURE-A, the permanent answer to 'recomputing uses current settings': every approved register now captures the ENTIRE non-secret Config sheet plus CompensationConfig into a new Payroll_Settings_Snapshot sheet, so from now on what a month's settings were is answered by reading, not guessing. Everything is captured rather than a curated pay-relevant list, because a hand-written list of keys that matter is the exact mistake that left a credential in an open endpoint. A new button on the FINALIZED panel lists every setting that has changed since the register was approved; for a month approved before snapshots existed it says so honestly instead of inventing an answer. FEATURE-B, the kiosk stops asking Apps Script who is in: hrms-punch v6 gains a read-only today op authorised by the kiosk's own punch key, returning today only and only empId, clock-in, clock-out, breaks and session - NO NAMES, no money - with punches from the last few minutes folded in so it is fresher than the 5-minute mirror. Measured live: 17 rows in 358ms against an Apps Script call that was failing outright during the 8.26am rush. Names are joined locally from a cache in this file, so no name ever travels on the punch key. No salary formula, no attendance rule, no payout value and no default is changed. // v490_four-live-faults 2026-08-03. Four faults hit on the live v489 build, all four root-caused against the running system. FAULT-1 the Rotate the Cloud Read Key button said 'Not changed: no reply from the backend' - PROVEN live from the owner's own browser that the POST was answered by Google's plain status page (body {status, app, version, ts}), so the command never ran and nothing was changed. Every slow-button POST now carries an explicit content type and a unique cache-buster, recognises that status-page reply, retries once by itself, and says exactly what happened if it recurs. FAULT-2 Google emailed that the mirror sync exceeded the 6-minute execution ceiling and was KILLED, leaving every table after it unsynced with no way to resume - the sync is now time-boxed to 4 minutes and resumable from a cursor, and the changed-since stamp only advances on a COMPLETE pass so a partial run can never look finished. FAULT-3 the kiosk told staff the attendance counts were UNKNOWN - that guard is correct and stays, but it now tries twice five seconds apart before saying anything, and repeats the warning at most once every ten minutes instead of every five. FAULT-4 Payroll refused to recompute a FINALIZED month and could only warn vaguely that current settings might differ. Most pay settings carry no history, so nobody can prove what July's settings were - guessing would be dishonest. So v490 MEASURES instead: a new read-only comparison runs the exact same computation the recompute would run, in memory, writes nothing anywhere, and reports employee by employee whether the saved register would change and by how many rupees. No salary formula, no attendance rule, no payout value and no default is changed anywhere in this release. // v489_kiosk-gets-its-own-key 2026-08-03. THE ROOT CAUSE OF THE 2 AUGUST LEAK IS NOW CLOSED, not just its surface. What was wrong: ONE key did two different jobs. The public config.json gave out the apiToken, the apiToken alone unlocked getReadToken, and the key that came back both READ the cloud copy AND was the key the punch function accepted - so a stranger could read Leaves and Attendance, and could also forge a clock-in. That key could not be locked down or changed either, because the kiosk on the factory floor is not signed in to anything and had nothing else to identify itself with: either change would have stopped every scan. THE FIX IS A SECOND KEY. The punch path now asks for its own credential (new action getPunchToken); the punch key records a punch and can read NOTHING, and the read key reads and cannot punch - both proven live on 2026-08-03 against the real Edge Functions. With the kiosk no longer needing the read key, the v487 login guard is turned ON: the cloud read key is now issued only to a device that is genuinely signed in. And because the read key is no longer holding the factory floor hostage, it can finally be CHANGED - two new Settings buttons in the Speed and Health card, Rotate the Cloud Read Key and Rotate the Kiosk Punch Key. A rotation pushes the new key to the cloud FIRST and only writes the sheet if the cloud accepted it, so a failed rotation changes nothing; the retired read key keeps working for a 15-minute grace window so no screen breaks mid-use; and every kiosk repairs itself after a punch-key rotation because its own 2-minute keep-warm ping is what notices the refusal. Every failure path ends in the untouched Apps Script route: slower for one scan, never wrong, never blocked. NOTHING about attendance, salary, leave or payroll logic is touched anywhere in this release, and the only setting changed anywhere is READTOKEN_REQUIRE_LOGIN off to on, which is the entire point of the release. // v488_payroll-page-shows-payroll 2026-08-02. THE REPORTED BUG, root-caused and fixed. Opening Payroll showed the DASHBOARD instead - sidebar said Payroll, title said Payroll, content was the dashboard - plus a stray warning toast, and it only came right after a third refresh. ROOT CAUSE: _v303TwoPhase is a fast-paint then authoritative-repaint helper. It paints instantly from the cloud copy, then fires a repaint callback when the slow Apps Script answer finally arrives. The dashboard's callback is renderDashboard(), which writes straight into admin-tab-content - and NOTHING checked whether the user was still on that screen. Apps Script takes 5-33 seconds, which is far longer than it takes to click Payroll, so the late answer landed on top of whatever screen had replaced it. Refreshing 'fixed' it only because it left no stale promise in flight. FIX-1: _v303TwoPhase now remembers which screen asked, and silently skips the repaint if the user has navigated away. One guarded change, all four call sites, and behaviour is byte-identical when the user has NOT moved. FIX-2: the kiosk Who-In-Out refresh ran on a global 5-minute timer and raised its warning toast on whatever screen happened to be open - it now does nothing unless its own panel is actually on screen. FIX-3: the Payroll empty state now names the month it is showing and says how to change it, because at the start of a month it defaults to the new month and reads as if the data had vanished. NO setting, salary rule, payout value or default is changed anywhere in this release. // v487_readtoken-login-and-narrow-reads 2026-08-02. (A) SECURITY, the root cause of today's leak. Proven live: the PUBLIC config.json gave the apiToken, that alone unlocked getReadToken, and that key returned every employee's salary, mobile, date of birth and home address. The exposed view was withdrawn immediately (hrms-read v5), but the door itself was still open and Leaves and Attendance were still reachable through it. getReadToken now requires a REAL SIGNED-IN SESSION - either a valid owner token or a valid HMAC role token, both of which every logged-in device already sends on every call (v91 P1). An anonymous caller holding only the public apiToken is refused. Failure is graceful by construction: _v265Init already falls back to Apps Script and _v474FastAck already returns null, so the worst case is slower, never broken. Kill switch Config READTOKEN_REQUIRE_LOGIN = off restores the old behaviour without a redeploy, and refusals are audit-logged once per 10 minutes so a legitimate caller cannot hide. (B) SPEED, the worst read in the app. _v327LoadTodayMap pulled the ENTIRE 1,671-row attendance table into the browser to build a map of TODAY - on the kiosk, on the punch path. It now asks for one day. _sbDirectRead gained optional date-range narrowing matching hrms-read v5 (dateCol/fromDate/toDate); every existing caller passes no range and is byte-identical. NO setting, no salary rule, no payout value, no default and no variable is changed anywhere in this release. // v486_where-pay-comes-from-and-scan-routes 2026-08-02. Two owner-visibility additions, both in the Speed & Health card so nothing has to be hunted for. (A) WHERE YOUR PAY IS CALCULATED FROM. The owner could not find the payroll-engine source setting -- it lives four cards further down in Advanced - Supabase Migration & Speed Control Center, which is a reasonable place to hide a switch and a terrible place to hide an ANSWER. The Speed & Health card now states it in one plain line every time the card is opened. It says Google Sheets, or Cloud copy in red, or -- if the check itself fails -- that it could not tell. It never guesses the safe answer. (B) WHICH ROAD DID RECENT SCANS TAKE. Until now a deferral left no trace anywhere: the Edge Function handed a reason to the browser and the reason died there, which is exactly why four versions were spent hunting a bug that did not exist. hrms-punch v4 now records every deferral fire-and-forget (not awaited, so it adds zero time to a scan), a new PunchDefers table holds them for 30 days, and a new button reports the last 24 hours grouped by reason in plain English. Also shown: the route the last scan on THIS device took. No attendance, salary, leave or payroll logic is touched. // v485_daily-health-report 2026-08-02. (A) DAILY HEALTH REPORT: a new Settings button, 'Send Me the Health Report Now', runs five live overnight checks and emails the verdict; the backend also sends it by itself at 07:00 every morning. The headline is built FROM the findings, and a check that could not be read is shown as a FAILURE, never as a pass. (B) PUNCH PATH VISIBILITY: the kiosk confirmation panel now states, in words, WHICH route the scan took -- Instant (about a quarter of a second) or the normal Google backend -- and when the instant route declined, WHY. Proven live on 2026-08-02: the reason the punch queue stayed empty through v474-v484 was never a bug; every test scan was past the 60-minute late-approval threshold and the Edge Function correctly sent it for approval instead. The system was right and simply never said so out loud. This makes it say so. No attendance, salary, leave or payroll logic is touched. // v484_instantpunch-reaches-the-kiosk 2026-08-02. THE BUG, found by auditing the live v482 app: Instant Punch was switched ON and working, yet PunchQueue was empty and Verify Every Punch reported Checked 0 scans. ROOT CAUSE: _v474FastAck was wired into only TWO places, the admin and ESS clockIn and clockOut functions. The KIOSK path that every QR, PIN and face scan on the factory floor goes through never called it at all. So the one screen that actually needed the quarter-second answer was still waiting the full several seconds on Apps Script, and the owner had been told the feature was on. It WAS on; it simply was not connected there. Every measurement, every safety net and every version note about Instant Punch since v474 was therefore true of the admin screen only. FIX: the kiosk punch path now asks for the same ~250ms verdict; on a clean yes it confirms to the employee, frees the kiosk, stops the scanner and releases the camera exactly as v479 requires, and lets the untouched Apps Script write run in the background with the same payload, same punchId, same handler, same Sheet and same salary engine. Any uncertainty defers to the original synchronous path unchanged. // v483_instantpunch-label-and-timesheet-autoretry 2026-08-02, two owner-reported faults, both diagnosed against the LIVE v482 app. FIX-1: the Instant Punch button always read Turn ON regardless of the real setting, so there was no way to tell its state without clicking it. Confirmed live that _v474FastOn was already true and az3_fastPunch was on -- the setting was correct all along, only the label lied. The label is now rendered from the live setting when the card is drawn, a permanent status line states ON or OFF in words, and a 3-second sync keeps it honest. FIX-2: the whole Timesheet week showed a question mark in every cell. The v473 guard was RIGHT to refuse to print a false absent mark, and the red banner was accurate -- but it was a dead end. Live re-verification proved the data was fine the entire time: BOTH paths returned 29 employees with real records for that exact week, the fetch had simply fired while the app was still booting. The screen now retries once by itself after four seconds, clearing its cached empty result first, and only shows the red banner if the retry also fails. Display-only; no attendance, leave or salary logic touched. // v482_failed-fetch-guard 2026-08-02. Makes the v473 Timesheet lesson reusable: a screen must never render a meaningful value -- an absent mark, a zero count, a rupee figure -- out of a fetch that failed or came back empty, because those are claims about reality and on a payroll system a wrong claim is worse than a visible error. New shared helper _v481Trustworthy. Applied to refreshWhoInOut, the kiosk Who-In-Out panel, which had no guard and rendered zero in / zero out when the call had simply failed. It now shows a question mark per count plus an explicit UNKNOWN warning. Display-only. NOTE TO FUTURE SELF: keep these changelog notes free of backtick characters -- a backtick pair in this comment broke the whole inline script in the first v481 attempt and node --check caught it. // v480_punch-reconciliation (2026-08-02). Instant Punch is ON by default from v479, so a scan is confirmed to the employee from Supabase in ~250ms while the authoritative Google Sheet write happens moments later in the background. That is safe by construction -- idempotent punchId, automatic replay, Sheets still the system of record -- but safe by construction is an ARGUMENT, not EVIDENCE, and this system pays people. v480 adds something that goes and CHECKS: a new read-only backend job compares every punch the fast path accepted against what is actually in the Attendance sheet and names anything missing, by employee and date. New Settings button 'Verify Every Punch Reached the Sheet' in the Speed & Health card, plus a nightly automatic run at 01:15 IST that writes a PUNCH_RECONCILE_ALERT to the Audit log if anything is missing -- so a silent loss cannot sit undiscovered until payroll day. Strictly read-only: never writes to Attendance, never touches pay, never modifies the queue. // v479_kiosk-stop-after-punch-and-instantpunch-default-on (2026-08-02). (A) KIOSK, owner-reported with video: 'the camera keeps showing the processing circle and stays open, it never says the scan is finished, and the next scan starts on top of it'. ROOT CAUSE: v432 FIX-B auto re-armed the scanner the instant a punch returned -- camera live again, QR detector running again, no completion state in between; v469's 8-second same-card debounce was treating the symptom. Applied the owner's rule instead: the scan screen CLOSES on a successful punch and the operator taps CLOCK IN / OUT again for the next person. The return path now hard-stops the QR loop, RELEASES the camera stream (stopping the loop alone left the video live, which is why the spinner stayed), and shows an unmissable bilingual confirmation panel with the employee name, IN/OUT and time, auto-clearing to the kiosk home after 6s. Nothing about the punch, the attendance write or pay is touched -- this is purely what happens on screen afterwards. (B) Instant Punch is now ON BY DEFAULT; only an explicit 'off' disables it. The automatic fallback is unchanged: any uncertainty in the Edge Function defers to the untouched Apps Script path. // v478_p0-triggerfix-and-safe-repair (2026-08-02, URGENT). v477 set the mirror-sync trigger to everyMinutes(3); Apps Script accepts ONLY 1/5/10/15/30, so the create threw -- and because the v474 self-healer deleted the old trigger BEFORE creating the replacement, sbAutoSyncTick was left with no trigger at all and the Supabase mirror sync stopped. Backend fix: interval 3->5, plus the self-healer now rejects an illegal interval before touching anything AND creates the replacement before deleting the old one, so a repair can never leave a job worse off. This file: the Check & Repair readout now shows any ERROR line in red with a red headline instead of burying it in a grey list (that is why the failure was easy to miss), and the Sentry organisation name in the test message follows the owner's rename to 'artzfolio'. // v477_syncgate-3min-and-readallowlist (2026-08-02, mostly a GAS + Supabase release; this file only adds the plain-language 'Cloud copy last refreshed N minutes ago' readout to the Check & Repair Triggers result). Backend: sbAutoSyncTick no longer reads all 17 mirrored tables in full every tick just to compute the MD5 that decides whether to skip -- one cheap Google Drive metadata call now answers 'has the spreadsheet been touched at all?', so an idle tick reads ZERO sheets. That is what allows the interval to go back DOWN from 15 to 3 minutes: faster, fresher AND lighter together. Safety: timestamp captured BEFORE the read so an edit during a sync is caught next tick; every 20th tick (~hourly) force-syncs regardless; any failure reading the timestamp behaves exactly as today. The v474 self-healer re-creates the trigger at the new 3-minute cadence on its own -- no manual reinstall. Supabase hrms-read v3 widened its allow-list by SIX company-wide reference tables only; every per-employee table stays out until Supabase Auth + RLS exists. // v476_slowbutton-patience-and-sentry-forceload (2026-08-02, two owner-reported v475 button faults, both root-caused live). FIX-01 'Test Error Reporting says crash reporting is not loaded': the Sentry LOADER script only installs a stub and defers the real SDK until the first crash, so window.sentryOnLoad never fired. Confirmed live: typeof Sentry==='object' with forceLoad/onLoad/init present but the SDK absent. Now Sentry.forceLoad() is called 10s after boot, and the test button uses Sentry.onLoad()+forceLoad() with a 12s honest timeout message. FIX-02 'Check & Repair Triggers -- could not check: no reply from the backend': the button used the shared API.call whose retry/timeout budget suits ordinary screens, but triggerHealth474 enumerates and can re-create GAS triggers and measured 5-30+ seconds live. The call was abandoned before Google answered and the error text wrongly implied a dead backend -- running the same action manually returned ok:true with ALL SIX background jobs healthy. Both slow owner buttons now use a dedicated _v476SlowCall with a 150s budget and a live on-screen seconds counter, and say 'busy, not broken' on timeout. No other call path touched. Carries v475/v474/v473. // v475_settings-buttons-and-crash-reporting (2026-08-02, owner feedback: "you keep telling me to run a function name or use the browser console -- where is the BUTTON?"). He was right; there was no UI at all for v474's new abilities. (1) NEW Settings card, exact label 'Speed & Health -- Instant Punch, Triggers, Queue', sitting directly ABOVE the existing 'Direct Read (skip GAS)' card, with four real buttons: 'Turn ON Instant Punch', 'Check & Repair Triggers' (calls triggerHealth474), 'Punch Queue Health' (calls punchQueueStats) and 'Test Error Reporting'. No console, no function names, plain-English result messages. (2) CRASH REPORTING via the Sentry loader script (public DSN key, safe in client code): async, fully try/catch-wrapped, nothing awaits it, so a blocked or slow CDN cannot affect the app. sendDefaultPii OFF; beforeSend redacts any key matching salary/ctc/pay/aadhaar/pan/bank/ifsc/token/password and drops the user object entirely; only the signed-in ROLE is tagged; replay and tracing both OFF. Flag az3_sentry='off' disables it. Carries v474 (instant punch + self-healing triggers) and v473 (3 fixes) unchanged. // v474_instant-punch-and-selfhealing-triggers (2026-08-02): (A) INSTANT PUNCH -- new Supabase Edge Function hrms-punch + PunchQueue table give a clock-in/out verdict in ~250ms (measured 310ms full round trip incl. all 4 index-backed queries) vs the Apps Script path which waits on an app-wide LockService lock shared by ~95 handlers AND reads the ENTIRE Attendance sheet while holding it. On a clean verdict the employee is confirmed and the kiosk freed IMMEDIATELY; the authoritative Apps Script write then runs in the background COMPLETELY UNCHANGED (same payload, same punchId, same handler, same Sheet, same salary engine), with the queued row as a replay safety net that cannot double-punch because punchId is idempotent (v327). Any uncertainty -- second punch same day, OT session, resume-after-clockout, late past the approval threshold, offline replay -- defers to the old path untouched. Flag az3_fastPunch, DEFAULT OFF: off = byte-identical to v473. (B) Carries v473's 3 fixes (Fast-Mode token cache-first, Timesheet loud-failure instead of a false 'A', bulk modals wait for the roster). Trigger self-healing is GAS-side, see the GAS changelog. // v473_fastmode-tokencache-timesheet-loudfail-rosterwait (2026-08-02, 3 owner-reported items, all root-caused against the LIVE app): (1) PERF -- _v265Init awaited a getReadToken GAS round-trip BEFORE reading the token already cached in localStorage, so Fast Mode was effectively OFF for the first ~2 min of every session (GAS measured 40-60s/call); now cache-first with a background refresh, stale-token path still falls back to GAS unchanged. (2) TIMESHEET all-blank/all-A -- renderTimesheets had no guard for an empty/errored getWeekAttendance result, so a slow or timed-out backend rendered a red A in every cell, indistinguishable from a real absence; live re-verification proved BOTH data paths return correct data (Supabase 1.06s, GAS 41.0s) so this was never data loss -- added a loud red banner + a gold ? cell instead of A. (3) BULK HOURS ENTRY 'No employees loaded' -- the bulk modals read the roster synchronously and bailed with a toast if it had not arrived; new _v473EnsureEmps() fetches on demand instead. Display/UX only: no salary, attendance, leave or payroll logic touched. // v472_autosync-interval-widen (2026-08-01, GAS-ONLY, this HTML file has zero logic changes this round -- version bumped purely for 4-way lockstep): live Google Apps Script Executions log showed sbAutoSyncTick (the Supabase Fast-Mode background mirror sync) occasionally taking up to 142s per run at its old 5-minute cadence -- root cause is the fixed cost of reading all 17 mirrored tables in full plus computing an MD5 signature on each, every single tick, regardless of whether the existing skip-if-unchanged optimization avoids the actual Supabase write. This is a standing background load competing with real user requests for the account's limited concurrent-execution slots, all day, not just during traffic bursts -- a likely major contributor to the general slowness reported. Widened to every 15 minutes in gas_backend_v472 (see GAS changelog); Fast Mode's 3 tables still refresh far more often than the pre-Fast-Mode daily-backup-only cadence. // v471_keepwarm-frequency-fix (2026-08-01)
const NETWORK_FIRST_HOSTS = ['cdn.jsdelivr.net','cdnjs.cloudflare.com','unpkg.com'];
self.addEventListener('install', e => { self.skipWaiting(); });
self.addEventListener('activate', e => {
  e.waitUntil(Promise.all([
    caches.keys().then(keys => Promise.all(keys.filter(k => k !== CACHE).map(k => caches.delete(k)))),
    self.clients.claim()
  ]));
});
self.addEventListener('message', e => { if (e.data && e.data.type === 'SKIP_WAITING') self.skipWaiting(); });
self.addEventListener('fetch', e => {
  const url = e.request.url;
  if (url.includes('script.google.com')) return;     // Never cache GAS API
  const isCdn = NETWORK_FIRST_HOSTS.some(h => url.includes(h));
  // v78: the app shell (this single-file HTML document + its inline JS = ALL of our code) is served
  // NETWORK-FIRST so a fresh deploy loads immediately and a fixed bug can never be masked by a stale
  // cached page (the recurring "the bug came back" trap). Offline still works via the cached fallback.
  // CDN libs stay network-first; other same-origin assets keep stale-while-revalidate.
  const isShell = e.request.mode === 'navigate' || e.request.destination === 'document' || url.indexOf('.html') !== -1;
  e.respondWith(caches.open(CACHE).then(async cache => {
    const cached = await cache.match(e.request);
    const fetchPromise = fetch(e.request).then(r => {
      // Only cache successful, opaque-safe responses
      if (r && r.ok && (r.type === 'basic' || r.type === 'cors')) {
        cache.put(e.request, r.clone()).catch(()=>{});
      }
      return r;
    }).catch(() => cached);
    return (isCdn || isShell) ? (await fetchPromise || cached) : (cached || fetchPromise);
  }));
});